#!/usr/bin/env python3
"""Compress web/dashboard.html into EmoDesk/web_ui.h (run after editing the dashboard)."""
import gzip, pathlib
root = pathlib.Path(__file__).resolve().parent.parent
html = (root / "web" / "dashboard.html").read_bytes()
gz = gzip.compress(html, compresslevel=9, mtime=0)
lines = []
for i in range(0, len(gz), 20):
    lines.append("  " + ",".join(f"0x{b:02x}" for b in gz[i:i + 20]) + ",")
out = (
    "// Generated by tools/build_ui.py from web/dashboard.html - do not edit by hand\n"
    "#pragma once\n#include <Arduino.h>\n"
    f"#define DASH_GZ_LEN {len(gz)}\n"
    "static const uint8_t DASH_GZ[] PROGMEM = {\n" + "\n".join(lines) + "\n};\n"
)
(root / "EmoDesk" / "web_ui.h").write_text(out)
print(f"dashboard.html {len(html)} bytes -> web_ui.h ({len(gz)} bytes gzipped)")
